<script setup>
import { EditOutlined, ReloadOutlined, SearchOutlined } from '@ant-design/icons-vue';
import { message } from 'ant-design-vue';
import { computed, onMounted, reactive, ref } from 'vue';
import { useStore } from 'vuex';
const store = useStore(); const orders = computed(() => store.getters.adminOrders); const loading = computed(() => store.getters.isLoading); const error = computed(() => store.getters.error); const filter = reactive({ keyword:'', status:undefined }); const modalOpen = ref(false); const selected = ref(null); const form = reactive({ status:'PENDING', paymentStatus:'UNPAID' });
const columns = [{ title:'Mã đơn', key:'code' },{ title:'Khách hàng', key:'customer' },{ title:'Tổng tiền', key:'total', align:'right' },{ title:'Đơn hàng', key:'status' },{ title:'Thanh toán', key:'payment' },{ title:'Thao tác', key:'action' }];
const formatCurrency = (value) => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(value||0);
const statusLabel = (status) => ({ PENDING:'Chờ xác nhận', CONFIRMED:'Đã xác nhận', COMPLETED:'Hoàn tất', CANCELLED:'Đã hủy', REFUND_REQUESTED:'Yêu cầu hoàn tiền', REFUNDED:'Đã hoàn tiền' }[status] || status);
async function loadOrders(){ try { await store.dispatch('fetchAdminOrders',{ keyword:filter.keyword||undefined,status:filter.status }); }catch{} }
function openEdit(order){ selected.value=order; Object.assign(form,{status:order.status,paymentStatus:order.paymentStatus}); modalOpen.value=true; }
async function save(){ try { await store.dispatch('updateAdminOrder',{ id:selected.value.id,data:form }); message.success('Đã cập nhật đơn hàng'); modalOpen.value=false; }catch{ message.error(store.getters.error||'Không thể cập nhật đơn'); } }
onMounted(loadOrders);
</script>
<template><section class="orders"><div class="heading"><div><span class="eyebrow">BÁN HÀNG</span><h1>Quản lý đơn hàng</h1></div><a-button @click="loadOrders"><reload-outlined /></a-button></div><a-card class="filter" :bordered="false"><a-input v-model:value="filter.keyword" placeholder="Mã đơn, khách hàng, điện thoại" @press-enter="loadOrders"><template #prefix><search-outlined /></template></a-input><a-select v-model:value="filter.status" allow-clear placeholder="Trạng thái"><a-select-option value="PENDING">Chờ xác nhận</a-select-option><a-select-option value="CONFIRMED">Đã xác nhận</a-select-option><a-select-option value="COMPLETED">Hoàn tất</a-select-option><a-select-option value="CANCELLED">Đã hủy</a-select-option></a-select><a-button type="primary" @click="loadOrders">Lọc</a-button></a-card><a-alert v-if="error" type="error" show-icon :message="error" class="error"/><a-card :bordered="false" class="table"><a-table :columns="columns" :data-source="orders" :loading="loading" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.key==='code'"><strong>{{ record.orderCode }}</strong><small>{{ new Date(record.createdAt).toLocaleString('vi-VN') }}</small></template><template v-else-if="column.key==='customer'"><span>{{ record.customerName }}</span><small>{{ record.customerPhone }}</small></template><template v-else-if="column.key==='total'"><strong>{{ formatCurrency(record.totalAmount) }}</strong></template><template v-else-if="column.key==='status'"><a-tag>{{ statusLabel(record.status) }}</a-tag></template><template v-else-if="column.key==='payment'"><a-tag :color="record.paymentStatus==='PAID'?'green':'gold'">{{ record.paymentStatus }}</a-tag></template><template v-else-if="column.key==='action'"><a-button type="text" @click="openEdit(record)"><edit-outlined /></a-button></template></template></a-table></a-card><a-modal v-model:open="modalOpen" title="Cập nhật đơn hàng" @ok="save"><a-form layout="vertical"><a-form-item label="Trạng thái đơn"><a-select v-model:value="form.status"><a-select-option value="PENDING">Chờ xác nhận</a-select-option><a-select-option value="CONFIRMED">Đã xác nhận</a-select-option><a-select-option value="COMPLETED">Hoàn tất</a-select-option><a-select-option value="CANCELLED">Đã hủy</a-select-option><a-select-option value="REFUND_REQUESTED">Yêu cầu hoàn tiền</a-select-option><a-select-option value="REFUNDED">Đã hoàn tiền</a-select-option></a-select></a-form-item><a-form-item label="Thanh toán"><a-select v-model:value="form.paymentStatus"><a-select-option value="UNPAID">Chưa thanh toán</a-select-option><a-select-option value="PAID">Đã thanh toán</a-select-option><a-select-option value="REFUNDED">Đã hoàn tiền</a-select-option></a-select></a-form-item></a-form></a-modal></section></template>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.eyebrow{color:#3f78c5;font-size:11px;font-weight:700;letter-spacing:1px}h1{margin:5px 0 0;font-size:30px}.filter,.table{border:1px solid #e6ebf4;border-radius:14px}.filter :deep(.ant-card-body){display:flex;gap:10px}.filter :deep(.ant-input),.filter :deep(.ant-select){max-width:280px}.error{margin:18px 0}small{display:block;color:#77849a;font-size:11px}@media(max-width:600px){.filter :deep(.ant-card-body){flex-direction:column}.filter :deep(.ant-input),.filter :deep(.ant-select){max-width:none}}</style>
